  (table) => [
    index("read_later_user_status_idx").using(
      "btree",
      table.user_id,
      table.status,
    ),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "read_later_state_user_id_users_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.saved_url_id],
      foreignColumns: [saved_urls.id],
      name: "read_later_state_saved_url_id_saved_urls_id_fk",
    }).onDelete("cascade"),
    unique("read_later_user_saved_url_unique").on(
      table.user_id,
      table.saved_url_id,
    ),
  ],
);

export const saved_urls = pgTable(
  "saved_urls",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    url: text().notNull(),
    normalized_url: text().notNull(),
    domain: varchar({ length: 255 }),
    title: text(),
    description: text(),
    favicon_url: text(),
    og_image_url: text(),
    summary: text(),
    extracted_text: text(),
    content_language: varchar({ length: 8 }),
    estimated_read_minutes: integer(),
    fetch_status: fetch_status().default("pending").notNull(),
    fetch_error: text(),
    search_vector: tsvector("search_vector"),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    tags: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    // hazy-note app domain: the rest of Item that has no home in the
    // read-later schema above. All additive/nullable — read_later_state
    // already carries status via fetch_status; these are new hazy fields.
    kind: source_kind().default("article").notNull(),
    points: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    suggested_tags: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    duration_label: text(),
    quote_candidates: integer().default(0).notNull(),
    related_note_id: uuid(),
    // Item.summary is a short bullet list; distinct from the pre-existing
    // free-text `summary` column above (used by the read-later app for a
    // prose blurb).
    summary_lines: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
  },
  (table) => [
    index("saved_urls_search_vector_idx").using("gin", table.search_vector),
    index("saved_urls_tags_idx").using("gin", table.tags),
    index("saved_urls_user_id_idx").using("btree", table.user_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "saved_urls_user_id_users_id_fk",
    }).onDelete("cascade"),
    unique("saved_urls_user_normalized_unique").on(
      table.user_id,
      table.normalized_url,
    ),
    foreignKey({
      columns: [table.related_note_id],
      foreignColumns: [notes.id],
      name: "saved_urls_related_note_id_notes_id_fk",
    }).onDelete("set null"),
  ],
);

// ─────────────────────────────────────────────────────────────
// hazy-note app domain — new tables (Note / CompareBoard / GraphData in
// lib/types.ts have no equivalent in the pre-existing read-later schema).
// The richly-shaped, still-canned-AI bits (note blocks, compare axes, graph
// nodes/edges) are kept as jsonb rather than fully normalized: they mirror
// the TS types in lib/types.ts directly and nothing else needs to query into
// their internals yet.
// ─────────────────────────────────────────────────────────────

export const notes = pgTable(
  "notes",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    collection_id: uuid(),
    title: text().notNull(),
    status: note_status().default("draft").notNull(),
    tags: jsonb().$type<{ label: string; tone: string }[]>().default([]).notNull(),
    blocks: jsonb().$type<unknown[]>().default([]).notNull(),
    sources: jsonb()
      .$type<{ n: number; label: string; cited: boolean }[]>()
      .default([])
      .notNull(),
    links: jsonb()
      .$type<{ noteId: string; title: string; reason: string }[]>()
      .default([])
      .notNull(),
    flags: jsonb()
      .$type<{ icon: string; tone: string; text: string }[]>()
      .default([])
      .notNull(),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("notes_user_id_idx").using("btree", table.user_id),
    index("notes_collection_id_idx").using("btree", table.collection_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "notes_user_id_users_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.collection_id],
      foreignColumns: [collections.id],
      name: "notes_collection_id_collections_id_fk",
    }).onDelete("set null"),
  ],
);

export const compare_boards = pgTable(
  "compare_boards",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    collection_id: uuid(),
    sources: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    axes: jsonb()
      .$type<{ name: string; values: (string | null)[]; accentCols: number[] }[]>()
      .default([])
      .notNull(),
    summary: text().default("").notNull(),
    candidate_axes: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("compare_boards_user_id_idx").using("btree", table.user_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "compare_boards_user_id_users_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.collection_id],
      foreignColumns: [collections.id],
      name: "compare_boards_collection_id_collections_id_fk",
    }).onDelete("set null"),
  ],
);

// One row per user: the whole GraphData blob (nodes/edges/isolated). Read-only
// from the API today (no merge/dismiss endpoint exists yet), so a single
// mutable snapshot is enough — no need to normalize into node/edge tables.
export const graph_snapshots = pgTable("graph_snapshots", {
  user_id: uuid().primaryKey().notNull(),
  nodes: jsonb().$type<unknown[]>().default([]).notNull(),
  edges: jsonb().$type<unknown[]>().default([]).notNull(),
  isolated: jsonb().$type<string[]>().default([]).notNull(),
  updated_at: timestamp({ withTimezone: true, mode: "string" })
    .defaultNow()
    .notNull(),
}, (table) => [
  foreignKey({
    columns: [table.user_id],
    foreignColumns: [users.id],
    name: "graph_snapshots_user_id_users_id_fk",
  }).onDelete("cascade"),
]);

=== hazy-note db/index ===
import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
import * as schema from "./schema";
import * as relations from "./relations";

// Next.js loads .env.local automatically; this just fails loudly if it is missing.
if (!process.env.DATABASE_URL) {
  throw new Error("DATABASE_URL is not set — check .env.local");
}

// Reuse one pool across dev hot-reloads instead of leaking a pool per reload,
// same pattern as the legacy in-memory store's globalThis.__hazyDB singleton.
const globalForDb = globalThis as unknown as { __hazyPool?: Pool };

const pool =
  globalForDb.__hazyPool ??
  new Pool({ connectionString: process.env.DATABASE_URL });

if (process.env.NODE_ENV !== "production") {
  globalForDb.__hazyPool = pool;
}

export const db = drizzle(pool, {
  schema: { ...schema, ...relations },
});

export { schema };

