import { and, desc, eq, isNull, sql } from "drizzle-orm";
import { db, schema } from "./index";
import { fetchAndExtract } from "@/lib/extract";
import {
  rewriteForExport,
  suggestConnections,
  summariseMemo,
  summariseSource,
  synthesiseCompare,
} from "@/lib/ai";
import type {
  Item,
  Note,
  NoteBlock,
  Project,
  Tag,
  CompareBoard,
  GraphData,
  Digest,
  SourceKind,
  ExportDraft,
  ExportFormat,
} from "@/lib/types";

// ─────────────────────────────────────────────────────────────
// Every function here is scoped by the caller's internal `users.id` (see
// lib/db/current-user.ts). This is the real replacement for lib/store.ts —
// same function names and return shapes, backed by Postgres instead of a
// mutable object on globalThis.
// ─────────────────────────────────────────────────────────────

function relativeLabel(iso: string): string {
  const min = Math.floor((Date.now() - new Date(iso).getTime()) / 60_000);
  if (min < 1) return "たった今";
  if (min < 60) return `${min}分前`;
  const hours = Math.floor(min / 60);
  if (hours < 24) return "今日";
  const days = Math.floor(hours / 24);
  return days === 1 ? "昨日" : `${days}日前`;
}

function kindFromUrl(url: string): SourceKind {
  const u = url.toLowerCase();
  if (u.includes("youtube") || u.includes("youtu.be") || u.includes("vimeo"))
    return "video";
  if (u.endsWith(".pdf") || u.includes("arxiv.org")) return "pdf";
  if (u.includes("twitter.com") || u.includes("x.com") || u.includes("bsky"))
    return "thread";
  return "article";
}

function siteFromUrl(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url.slice(0, 40);
  }
}

function normalizeUrl(url: string): string {
  try {
    const u = new URL(url);
    return `${u.hostname.replace(/^www\./, "")}${u.pathname.replace(/\/+$/, "")}${u.search}`.toLowerCase();
  } catch {
    return url.trim().toLowerCase();
  }
}

// ── Items ──────────────────────────────────────────────────
type SavedUrlWithLinks = typeof schema.saved_urls.$inferSelect & {
  collection_items: { collection_id: string }[];
};

function toItem(row: SavedUrlWithLinks): Item {
  const site =
    row.kind === "note" ? (row.domain ?? "メモ") : (row.domain ?? siteFromUrl(row.url));
  return {
    id: row.id,
    url: row.url,
    kind: row.kind as SourceKind,
    site,
    title: row.title ?? site,
    addedAt: new Date(row.created_at).toISOString(),
    addedLabel: relativeLabel(row.created_at),
    status: row.fetch_status === "success" ? "ready" : row.fetch_status === "error" ? "ready" : "reading",
    durationLabel: row.duration_label ?? undefined,
    summary: row.summary_lines,
    points: row.points,
    suggestedTags: row.suggested_tags,
    tags: row.tags,
    projectId: row.collection_items[0]?.collection_id ?? null,
    quoteCandidates: row.quote_candidates,
    relatedNoteId: row.related_note_id ?? undefined,
  };
}

export async function listItems(userId: string): Promise<Item[]> {
  const rows = await db.query.saved_urls.findMany({
    where: (t, { eq }) => eq(t.user_id, userId),
    with: { collection_items: true },
    orderBy: (t, { desc }) => [desc(t.created_at)],
  });
  return rows.map(toItem);
}

export async function getItem(userId: string, id: string): Promise<Item | undefined> {
  const row = await db.query.saved_urls.findFirst({
    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
    with: { collection_items: true },
  });
  return row ? toItem(row) : undefined;
}

export async function addItem(userId: string, url: string): Promise<Item> {
  const site = siteFromUrl(url);
  const [row] = await db
    .insert(schema.saved_urls)
    .values({
      user_id: userId,
      url,
      normalized_url: normalizeUrl(url),
      domain: site,
      title: site,
      kind: kindFromUrl(url),
      fetch_status: "pending",
    })
    .onConflictDoUpdate({
      target: [schema.saved_urls.user_id, schema.saved_urls.normalized_url],
      set: { fetch_status: "pending", updated_at: new Date().toISOString() },
    })
    .returning();
  return (await getItem(userId, row.id))!;
}

/**
 * POST /api/items — the "Hazyから追加" path. A pasted memo becomes an item with
 * no external URL; `kind: "note"` and the raw text lives in `extracted_text`.
 */
export async function addMemo(userId: string, text: string): Promise<Item> {
  const token = `hazy:memo:${crypto.randomUUID()}`;
  const firstLine = text.trim().split("\n")[0].trim();
  const title =
    firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine || "メモ";
  const [row] = await db
    .insert(schema.saved_urls)
    .values({
      user_id: userId,
      url: token,
      normalized_url: token,
      domain: "メモ",
      title,
      kind: "note",
      extracted_text: text,
      fetch_status: "pending",
    })
    .returning();
  return (await getItem(userId, row.id))!;
}

/**
 * POST /api/items/:id/read — the "読み取り" step. For a URL this fetches the
 * page, extracts its text, and asks the model for a summary + tags. For a
 * pasted memo it just distils what was written. Best-effort: a fetch or AI
 * failure still resolves the item (fetch_status "error") instead of throwing.
 */
export async function finishReading(userId: string, id: string): Promise<Item | undefined> {
  const existing = await db.query.saved_urls.findFirst({
    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
  });
  if (!existing) return undefined;

  if (existing.kind === "note") {
    const digest = await summariseMemo(existing.extracted_text ?? "");
    await db
      .update(schema.saved_urls)
      .set({
        fetch_status: "success",
        summary_lines: digest.summary,
        points: digest.points,
        suggested_tags: digest.suggestedTags,
        updated_at: new Date().toISOString(),
      })
      .where(eq(schema.saved_urls.id, id));
    return getItem(userId, id);
  }

  let extracted;
  try {
    extracted = await fetchAndExtract(existing.url);
  } catch (e) {
    await db
      .update(schema.saved_urls)
      .set({
        fetch_status: "error",
        fetch_error: (e as Error).message.slice(0, 500),
        updated_at: new Date().toISOString(),
      })
      .where(eq(schema.saved_urls.id, id));
    return getItem(userId, id);
  }

  const title =
    extracted.title?.trim() ||
    (existing.title && existing.title !== existing.domain
      ? existing.title
      : (existing.domain ?? siteFromUrl(existing.url)));

  const digest = await summariseSource({
    title,
    text: extracted.text,
    kind: existing.kind,
  });

  await db
    .update(schema.saved_urls)
    .set({
      fetch_status: "success",
      title: digest.title?.trim() || title,
      description: extracted.description ?? existing.description,
      favicon_url: extracted.favicon ?? existing.favicon_url,
      og_image_url: extracted.ogImage ?? existing.og_image_url,
      extracted_text: extracted.text || existing.extracted_text,
      content_language: extracted.lang ?? existing.content_language,
      estimated_read_minutes: extracted.readMinutes ?? existing.estimated_read_minutes,
      duration_label:
        existing.duration_label ??
        (extracted.readMinutes ? `読了${extracted.readMinutes}分` : null),
      summary_lines: digest.summary,
      points: digest.points,
      suggested_tags: digest.suggestedTags,
      updated_at: new Date().toISOString(),
    })
    .where(eq(schema.saved_urls.id, id));
  return getItem(userId, id);
}

export async function updateItem(
  userId: string,
  id: string,
  patch: Partial<Pick<Item, "tags" | "projectId" | "title" | "summary">>,
): Promise<Item | undefined> {
  const existing = await getItem(userId, id);
  if (!existing) return undefined;

  const colPatch: Partial<typeof schema.saved_urls.$inferInsert> = {};
  if (patch.tags) colPatch.tags = patch.tags;
  if (patch.title !== undefined) colPatch.title = patch.title;
  if (patch.summary) colPatch.summary_lines = patch.summary;
  if (Object.keys(colPatch).length) {
    colPatch.updated_at = new Date().toISOString();
    await db.update(schema.saved_urls).set(colPatch).where(eq(schema.saved_urls.id, id));
  }

  if ("projectId" in patch) {
    await db.delete(schema.collection_items).where(eq(schema.collection_items.saved_url_id, id));
    if (patch.projectId) {
      await db
        .insert(schema.collection_items)
        .values({ collection_id: patch.projectId, saved_url_id: id });
    }
  }

  return getItem(userId, id);
}

export async function deleteItem(userId: string, id: string): Promise<boolean> {
  const deleted = await db
    .delete(schema.saved_urls)
    .where(and(eq(schema.saved_urls.id, id), eq(schema.saved_urls.user_id, userId)))
    .returning({ id: schema.saved_urls.id });
  return deleted.length > 0;
}

/** POST /api/items/sort — the "まとめて振り分け" digest action. */
export async function autoSort(userId: string): Promise<{ moved: number }> {
  const target = await db.query.collections.findFirst({
    where: (c, { and, eq }) => and(eq(c.user_id, userId), eq(c.tone, "accent")),
  });
  if (!target) return { moved: 0 };

  const unsorted = await db
    .select({ id: schema.saved_urls.id })
    .from(schema.saved_urls)
    .leftJoin(
      schema.collection_items,
      eq(schema.collection_items.saved_url_id, schema.saved_urls.id),
    )
    .where(
      and(
        eq(schema.saved_urls.user_id, userId),
        isNull(schema.collection_items.id),
        sql`cardinality(${schema.saved_urls.suggested_tags}) > 0`,
      ),
    );
  if (!unsorted.length) return { moved: 0 };

  await db
    .insert(schema.collection_items)
    .values(unsorted.map((u) => ({ collection_id: target.id, saved_url_id: u.id })));
  return { moved: unsorted.length };
}

// ── Projects & Tags ───────────────────────────────────────────
export async function listProjects(userId: string): Promise<Project[]> {
  const rows = await db
    .select({
      id: schema.collections.id,
      name: schema.collections.name,
      tone: schema.collections.tone,
      count: sql<number>`count(${schema.collection_items.id})::int`,
    })
    .from(schema.collections)
    .leftJoin(
      schema.collection_items,
      eq(schema.collection_items.collection_id, schema.collections.id),
    )
    .where(eq(schema.collections.user_id, userId))
    .groupBy(schema.collections.id)
    .orderBy(schema.collections.created_at);
  return rows.map((r) => ({
    id: r.id,
    name: r.name,
    tone: r.tone === "accent" ? "accent" : "neutral",
    count: r.count,
  }));
}

export async function createProject(
  userId: string,
  name: string,
  tone: "accent" | "neutral" = "neutral",
): Promise<Project> {
  const [row] = await db
    .insert(schema.collections)
    .values({ user_id: userId, name: name.trim() || "無題", tone })
    .returning();
  return { id: row.id, name: row.name, tone: row.tone === "accent" ? "accent" : "neutral", count: 0 };
}

export async function updateProject(
  userId: string,
  id: string,
  patch: { name?: string; tone?: "accent" | "neutral" },
): Promise<Project | undefined> {
  const set: Partial<typeof schema.collections.$inferInsert> = {};
  if (patch.name !== undefined) set.name = patch.name.trim() || "無題";
  if (patch.tone !== undefined) set.tone = patch.tone;
  if (Object.keys(set).length) {
    set.updated_at = new Date().toISOString();
    await db
      .update(schema.collections)
      .set(set)
      .where(and(eq(schema.collections.id, id), eq(schema.collections.user_id, userId)));
  }
  return (await listProjects(userId)).find((p) => p.id === id);
}

export async function deleteProject(userId: string, id: string): Promise<boolean> {
  const deleted = await db
    .delete(schema.collections)
    .where(and(eq(schema.collections.id, id), eq(schema.collections.user_id, userId)))
    .returning({ id: schema.collections.id });
  return deleted.length > 0;
}

export async function listTags(userId: string): Promise<Tag[]> {
  const rows = await db.execute<{ label: string; n: number }>(sql`
    select label, count(*)::int as n
    from saved_urls, unnest(tags) as label
    where user_id = ${userId}
    group by label
    order by n desc, label
  `);
  return rows.rows.map((r) => ({
    id: `t-${encodeURIComponent(r.label)}`,
    label: r.label,
    tone: "neutral",
    count: r.n,
  }));
}

export async function getDigest(userId: string): Promise<Digest> {
  const [row] = await db
    .select({
      unsorted: sql<number>`count(*) filter (where ${schema.collection_items.id} is null)::int`,
      guess: sql<number>`count(*) filter (where ${schema.collection_items.id} is null and cardinality(${schema.saved_urls.suggested_tags}) > 0)::int`,
    })
    .from(schema.saved_urls)
    .leftJoin(
      schema.collection_items,
      eq(schema.collection_items.saved_url_id, schema.saved_urls.id),
    )
    .where(eq(schema.saved_urls.user_id, userId));

  const target = await db.query.collections.findFirst({
    where: (c, { and, eq }) => and(eq(c.user_id, userId), eq(c.tone, "accent")),
  });

  const unsorted = row?.unsorted ?? 0;
  const guess = row?.guess ?? 0;
  return {
    unsorted,
    message:
      guess > 0 && target
        ? `未整理が${unsorted}件。${guess}件は「${target.name}」に入りそうです。`
        : `未整理が${unsorted}件。`,
  };
}

// ── Notes ──────────────────────────────────────────────────
function toNote(row: typeof schema.notes.$inferSelect): Note {
  return {
    id: row.id,
    title: row.title,
    projectId: row.collection_id ?? "",
    tags: row.tags as Note["tags"],
    status: row.status,
    updatedLabel: `自動保存 · ${relativeLabel(row.updated_at)}`,
    blocks: row.blocks as NoteBlock[],
    sources: row.sources as Note["sources"],
    links: row.links as Note["links"],
    flags: row.flags as Note["flags"],
  };
}

export async function listNotes(userId: string): Promise<Note[]> {
  const rows = await db.query.notes.findMany({
    where: (t, { eq }) => eq(t.user_id, userId),
    orderBy: (t, { desc }) => [desc(t.updated_at)],
  });
  return rows.map(toNote);
}

export async function createNote(
  userId: string,
  input: { title?: string; projectId?: string | null; text?: string } = {},
): Promise<Note> {
  const blocks: NoteBlock[] = input.text?.trim()
    ? [{ type: "p", text: input.text.trim() }]
    : [];
  const [row] = await db
    .insert(schema.notes)
    .values({
      user_id: userId,
      collection_id: input.projectId || null,
      title: input.title?.trim() || "無題のノート",
      status: "draft",
      tags: [],
      blocks,
      sources: [],
      links: [],
      flags: [],
    })
    .returning();
  return toNote(row);
}

export async function updateNote(
  userId: string,
  id: string,
  patch: Partial<Pick<Note, "title" | "status" | "projectId" | "blocks" | "tags">>,
): Promise<Note | undefined> {
  const row = await getNoteRow(userId, id);
  if (!row) return undefined;
  const set: Partial<typeof schema.notes.$inferInsert> = {
    updated_at: new Date().toISOString(),
  };
  if (patch.title !== undefined) set.title = patch.title.trim() || "無題のノート";
  if (patch.status !== undefined) set.status = patch.status;
  if (patch.projectId !== undefined) set.collection_id = patch.projectId || null;
  if (patch.blocks !== undefined) set.blocks = patch.blocks;
  if (patch.tags !== undefined) set.tags = patch.tags;
  await db.update(schema.notes).set(set).where(eq(schema.notes.id, id));
  return getNote(userId, id);
}

export async function deleteNote(userId: string, id: string): Promise<boolean> {
  const deleted = await db
    .delete(schema.notes)
    .where(and(eq(schema.notes.id, id), eq(schema.notes.user_id, userId)))
    .returning({ id: schema.notes.id });
  return deleted.length > 0;
}

export async function getNote(userId: string, id: string): Promise<Note | undefined> {
  const row = await db.query.notes.findFirst({
    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
  });
  return row ? toNote(row) : undefined;
}

async function getNoteRow(userId: string, id: string) {
  return db.query.notes.findFirst({
    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
  });
}

export async function acceptSuggestion(
  userId: string,
  noteId: string,
  blockIndex: number,
): Promise<Note | undefined> {
  const row = await getNoteRow(userId, noteId);
  if (!row) return undefined;
  const blocks = row.blocks as NoteBlock[];
  const block = blocks[blockIndex];
  if (block && block.type === "suggestion") {
    blocks[blockIndex] = { type: "p", text: block.text, refs: block.ref };
    // Drop any "未着手 / 未執筆 / 下書き" style flag now that the block is filled.
    const flags = (row.flags as Note["flags"]).filter(
      (f) => !/未着手|未執筆|下書き|未完/.test(f.text),
    );
    await db
      .update(schema.notes)
      .set({ blocks, flags, updated_at: new Date().toISOString() })
      .where(eq(schema.notes.id, noteId));
  }
  return getNote(userId, noteId);
}

export async function dismissSuggestion(
  userId: string,
  noteId: string,
  blockIndex: number,
): Promise<Note | undefined> {
  const row = await getNoteRow(userId, noteId);
  if (!row) return undefined;
  const blocks = row.blocks as NoteBlock[];
  if (blocks[blockIndex]?.type === "suggestion") {
    blocks.splice(blockIndex, 1);
    await db
      .update(schema.notes)
      .set({ blocks, updated_at: new Date().toISOString() })
      .where(eq(schema.notes.id, noteId));
  }
  return getNote(userId, noteId);
}

export async function appendParagraph(
  userId: string,
  noteId: string,
  text: string,
): Promise<Note | undefined> {
  const row = await getNoteRow(userId, noteId);
  if (!row) return undefined;
  const blocks = [...(row.blocks as NoteBlock[]), { type: "p" as const, text }];
  await db
    .update(schema.notes)
    .set({ blocks, updated_at: new Date().toISOString() })
    .where(eq(schema.notes.id, noteId));
  return getNote(userId, noteId);
}

// ── Compare ────────────────────────────────────────────────
function toCompare(row: typeof schema.compare_boards.$inferSelect): CompareBoard {
  return {
    id: row.id,
    projectId: row.collection_id ?? "",
    sources: row.sources,
    axes: row.axes as CompareBoard["axes"],
    summary: row.summary,
    candidateAxes: row.candidate_axes,
  };
}

export async function getCompare(userId: string): Promise<CompareBoard | undefined> {
  const row = await db.query.compare_boards.findFirst({
    where: (t, { eq }) => eq(t.user_id, userId),
    orderBy: (t, { desc }) => [desc(t.updated_at)],
  });
  return row ? toCompare(row) : undefined;
}

/**
 * "差分をまとめる" — (re)build the compare board from the ready sources in a
 * project (or, with no project, every ready source). Needs ≥2 sources.
 */
export async function buildCompareBoard(
  userId: string,
  projectId?: string,
): Promise<CompareBoard> {
  const rows = await db.query.saved_urls.findMany({
    where: (t, { and, eq }) =>
      and(eq(t.user_id, userId), eq(t.fetch_status, "success")),
    with: { collection_items: true },
    orderBy: (t, { desc }) => [desc(t.created_at)],
  });
  const items = rows
    .map(toItem)
    .filter((it) => (projectId ? it.projectId === projectId : true))
    .filter((it) => it.summary.length > 0)
    .slice(0, 8);

  const synth = await synthesiseCompare(
    items.map((it) => ({ title: it.title, summary: it.summary })),
  );

  await db
    .delete(schema.compare_boards)
    .where(
      and(
        eq(schema.compare_boards.user_id, userId),
        projectId
          ? eq(schema.compare_boards.collection_id, projectId)
          : isNull(schema.compare_boards.collection_id),
      ),
    );
  const [row] = await db
    .insert(schema.compare_boards)
    .values({
      user_id: userId,
      collection_id: projectId ?? null,
      sources: items.map((it) => it.title),
      axes: synth.axes,
      summary: synth.summary,
      candidate_axes: synth.candidateAxes,
    })
    .returning();
  return toCompare(row);
}

// ── Graph ──────────────────────────────────────────────────
const GRAPH_W = 840;
const GRAPH_H = 600;

/** Deterministic ring layout so re-renders don't jump nodes around. */
function ringLayout(n: number, i: number, radius: number) {
  if (n === 1) return { x: GRAPH_W / 2, y: GRAPH_H / 2 };
  const a = (i / n) * Math.PI * 2 - Math.PI / 2;
  return {
    x: Math.round(GRAPH_W / 2 + Math.cos(a) * radius),
    y: Math.round(GRAPH_H / 2 + Math.sin(a) * radius),
  };
}

export async function buildGraph(userId: string): Promise<GraphData> {
  const notes = await listNotes(userId);
  const sourceRows = await db.query.saved_urls.findMany({
    where: (t, { and, eq }) =>
      and(eq(t.user_id, userId), eq(t.fetch_status, "success")),
    with: { collection_items: true },
    orderBy: (t, { desc }) => [desc(t.created_at)],
  });
  const sources = sourceRows.map(toItem).slice(0, 12);

  const noteIds = new Set(notes.map((n) => n.id));
  const nodes: GraphData["nodes"] = [
    ...notes.map((n, i) => ({
      id: n.id,
      label: n.title,
      kind: "note" as const,
      ...ringLayout(Math.max(notes.length, 1), i, notes.length > 3 ? 150 : 90),
      r: 40,
      focus: i === 0 && notes.length > 0,
    })),
    ...sources.map((s, i) => ({
      id: s.id,
      label: s.title,
      kind: "source" as const,
      ...ringLayout(Math.max(sources.length, 1), i, 250),
      r: 26,
    })),
  ];

  const edges: GraphData["edges"] = [];
  // note → note links the user (or a prior AI pass) already recorded.
  for (const n of notes) {
    for (const l of n.links) {
      if (noteIds.has(l.noteId) && n.id < l.noteId) {
        edges.push({
          id: `c-${n.id}-${l.noteId}`,
          from: n.id,
          to: l.noteId,
          kind: "citation",
          title: `${n.title} ↔ ${l.title}`,
          reason: l.reason,
        });
      }
    }
  }
  // source → note when the capture was filed against a note.
  for (const s of sources) {
    if (s.relatedNoteId && noteIds.has(s.relatedNoteId)) {
      edges.push({
        id: `c-${s.id}-${s.relatedNoteId}`,
        from: s.id,
        to: s.relatedNoteId,
        kind: "citation",
        title: `${s.title} → ノート`,
      });
    }
  }
  // AI-guessed connections between anything not already linked.
  const linked = new Set(edges.flatMap((e) => [e.from, e.to]));
  const guesses = await suggestConnections([
    ...notes.map((n) => ({
      id: n.id,
      label: n.title,
      text: n.blocks.map((b) => ("text" in b ? b.text : "")).join(" "),
    })),
    ...sources.map((s) => ({ id: s.id, label: s.title, text: s.summary.join(" ") })),
  ]);
  for (const g of guesses) {
    const key = [g.from, g.to].sort().join("-");
    if (edges.some((e) => [e.from, e.to].sort().join("-") === key)) continue;
    edges.push({ id: `h-${key}`, from: g.from, to: g.to, kind: "hypothesis", reason: g.reason });
    linked.add(g.from);
    linked.add(g.to);
  }

  const isolated = [...notes, ...sources]
    .filter((x) => !linked.has(x.id) && !edges.some((e) => e.from === x.id || e.to === x.id))
    .map((x) => ("title" in x ? x.title : ""))
    .filter(Boolean);

  await db
    .insert(schema.graph_snapshots)
    .values({ user_id: userId, nodes, edges, isolated })
    .onConflictDoUpdate({
      target: schema.graph_snapshots.user_id,
      set: { nodes, edges, isolated, updated_at: new Date().toISOString() },
    });
  return { nodes, edges, isolated };
}

export async function getGraph(userId: string): Promise<GraphData> {
  const row = await db.query.graph_snapshots.findFirst({
    where: (t, { eq }) => eq(t.user_id, userId),
  });
  if (row) {
    return {
      nodes: row.nodes as GraphData["nodes"],
      edges: row.edges as GraphData["edges"],
      isolated: row.isolated as string[],
    };
  }
  return buildGraph(userId);
}

// ── Export ─────────────────────────────────────────────────
function countChars(blocks: { text?: string }[]): number {
  return blocks.reduce((n, b) => n + (b.text?.length ?? 0), 0);
}

export async function buildExport(
  userId: string,
  noteId: string,
  format: ExportFormat = "blog",
): Promise<ExportDraft> {
  let note = await getNote(userId, noteId);
  if (!note) {
    const fallback = await db.query.notes.findFirst({
      where: (t, { eq }) => eq(t.user_id, userId),
      orderBy: (t, { desc }) => [desc(t.updated_at)],
    });
    note = fallback ? toNote(fallback) : undefined;
  }
  if (!note) {
    return {
      format,
      meta: "ノートがありません",
      title: "書き出すノートがありません",
      blocks: [{ type: "p", text: "先にノートを作成してください。" }],
      provenance: [],
    };
  }

  const draft = await rewriteForExport({
    title: note.title,
    blocks: note.blocks,
    format,
  });
  const chars = countChars(draft.blocks);
  const minutes = Math.max(1, Math.round(chars / 500));
  const meta =
    format === "bullets"
      ? `${draft.blocks.filter((b) => b.type === "p").length}項目`
      : `約${chars.toLocaleString()}字 · 読了${minutes}分`;

  return { format, meta, ...draft };
}

