import { relations } from "drizzle-orm/relations";
import {
  users,
  collections,
  user_preferences,
  collection_items,
  saved_urls,
  ask_threads,
  ask_messages,
  ask_message_citations,
  read_later_state,
  notes,
  compare_boards,
  graph_snapshots,
} from "./schema";

export const usersRelations = relations(users, ({ many, one }) => ({
  collections: many(collections),
  user_preferences: many(user_preferences),
  ask_threads: many(ask_threads),
  read_later_states: many(read_later_state),
  saved_urls: many(saved_urls),
  notes: many(notes),
  compare_boards: many(compare_boards),
  graph_snapshot: one(graph_snapshots, {
    fields: [users.id],
    references: [graph_snapshots.user_id],
  }),
}));

export const collectionsRelations = relations(collections, ({ one, many }) => ({
  user: one(users, {
    fields: [collections.user_id],
    references: [users.id],
  }),
  collection_items: many(collection_items),
  notes: many(notes),
  compare_boards: many(compare_boards),
}));

export const notesRelations = relations(notes, ({ one }) => ({
  user: one(users, {
    fields: [notes.user_id],
    references: [users.id],
  }),
  collection: one(collections, {
    fields: [notes.collection_id],
    references: [collections.id],
  }),
}));

export const compare_boardsRelations = relations(compare_boards, ({ one }) => ({
  user: one(users, {
    fields: [compare_boards.user_id],
    references: [users.id],
  }),
  collection: one(collections, {
    fields: [compare_boards.collection_id],
    references: [collections.id],
  }),
}));

export const graph_snapshotsRelations = relations(graph_snapshots, ({ one }) => ({
  user: one(users, {
    fields: [graph_snapshots.user_id],
    references: [users.id],
  }),
}));

export const user_preferencesRelations = relations(
  user_preferences,
  ({ one }) => ({
    user: one(users, {
      fields: [user_preferences.user_id],
      references: [users.id],
    }),
  }),
);

export const collection_itemsRelations = relations(
  collection_items,
  ({ one }) => ({
    collection: one(collections, {
      fields: [collection_items.collection_id],
      references: [collections.id],
    }),
    saved_url: one(saved_urls, {
      fields: [collection_items.saved_url_id],
      references: [saved_urls.id],
    }),
  }),
);

export const saved_urlsRelations = relations(saved_urls, ({ one, many }) => ({
  user: one(users, {
    fields: [saved_urls.user_id],
    references: [users.id],
  }),
  collection_items: many(collection_items),
