// ── Shared with hazy-note ──────────────────────────────────────────────
// hazy and hazy-note run against the same database (same Clerk tenant, same
// `users` / `saved_urls` / `collections`). hazy-note adds the enums, columns,
// and tables below for its capture → notes → compare → graph → export flow.
// They're all additive and defaulted, so hazy's own reads/writes ignore them,
// but they must live here too — otherwise `bun run db:push` from this repo
// sees them as drift and proposes dropping them. Keep in sync with
// hazy-note/lib/db/schema.ts (introspected from this same database).
export const sourceKindEnum = pgEnum("source_kind", [
  "article",
  "pdf",
  "video",
  "thread",
  "note",
]);
export const noteStatusEnum = pgEnum("note_status", ["draft", "done"]);

