import { listImportable } from "@/lib/db/repo";
import { db, schema } from "@/lib/db/index";
import { eq } from "drizzle-orm";

async function main() {
  const u = await db.query.users.findFirst({
    where: (t, { eq }) => eq(t.email, "n.knight.pc0627@gmail.com"),
  });
  if (!u) return console.log("no user");

  // Simulate a URL saved via the hazy app (success fetch, no hazy-note fields).
  const [row] = await db
    .insert(schema.saved_urls)
    .values({
      user_id: u.id,
      url: "https://example.com/from-hazy-" + Date.now(),
      normalized_url: "example.com/from-hazy-" + Date.now(),
      domain: "example.com",
      title: "Hazyで保存した記事",
      fetch_status: "success",
    })
    .returning();
  console.log("inserted", row.id);

  let imp = await listImportable(u.id);
  console.log("importable after insert:", imp.map((i) => i.title));

  // File it into a collection → should drop out of importable.
  const col = await db.query.collections.findFirst({
    where: (t, { eq }) => eq(t.user_id, u.id),
  });
  await db.insert(schema.collection_items).values({
    collection_id: col!.id,
    saved_url_id: row.id,
  });
  imp = await listImportable(u.id);
  console.log("importable after filing:", imp.map((i) => i.title));

  // cleanup
  await db.delete(schema.saved_urls).where(eq(schema.saved_urls.id, row.id));
  console.log("cleaned up");
}
main().then(() => process.exit(0));

