export function Sidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const [projects, setProjects] = useState<Project[]>([]);
  const [tags, setTags] = useState<TagT[]>([]);
  const [digest, setDigest] = useState<Digest | null>(null);
  const [sorting, setSorting] = useState(false);

  const load = () => {
    api.projects().then(setProjects).catch(() => {});
    api.tags().then(setTags).catch(() => {});
    api.digest().then(setDigest).catch(() => {});
  };
  useEffect(load, [pathname]);

  async function sortAll() {
    setSorting(true);
    try {
      await api.autoSort();
      load();
      router.refresh();
    } finally {
      setSorting(false);
    }
  }

  async function addProject() {
    const name = window.prompt("プロジェクト名");
    if (!name?.trim()) return;
    await api.addProject(name.trim());
    load();
  }

  return (
    <aside className="sticky top-0 flex h-screen w-[220px] shrink-0 flex-col gap-5 overflow-y-auto border-r border-white/[0.06] bg-neutral-900 p-[18px_13px]">
      <div className="flex items-center gap-[9px] px-[7px]">
        <Link href="/library" className="flex flex-1 items-center gap-[9px] no-underline">
          <span className="h-[22px] w-[22px] rounded-[7px] bg-[radial-gradient(circle_at_30%_25%,var(--color-accent-400),var(--color-accent-700))] shadow-[0_0_14px_rgba(145,132,217,0.45)]" />
          <span className="text-[15px] font-medium tracking-[-0.01em] text-text">
            hazy note
          </span>
        </Link>
        <UserButton />
      </div>

      <nav className="flex flex-col gap-[2px]">
        {NAV.map((n) => {
          const active =
            pathname === n.href || pathname.startsWith(n.href + "/");
          return (
            <Link
              key={n.href}
              href={n.href}
              className={`flex items-center gap-[10px] rounded-lg px-[10px] py-[7px] text-[13px] no-underline ${
                active
                  ? "bg-accent/[0.12] text-accent"
                  : "text-text hover:bg-white/[0.04]"
              }`}
            >
              <Icon name={n.icon} size={16} />
              {n.label}
            </Link>
          );
        })}
      </nav>

      <div className="flex flex-col gap-[7px]">
        <div className="flex items-center px-[10px] text-[10px] uppercase tracking-[0.1em] text-text/[0.38]">
          プロジェクト
          <button
            onClick={addProject}
            className="ml-auto text-text/50 hover:text-text"
            title="プロジェクトを追加"
          >
            <Icon name="plus" size={12} />
          </button>
        </div>
        <div className="flex flex-col gap-px">
          {projects.length === 0 && (
            <div className="px-[10px] py-1 text-[11px] text-text/35">
              まだありません
            </div>
          )}
          {projects.map((p) => (
            <Link
              key={p.id}
              href={`/library?project=${p.id}`}
              className="flex items-center gap-[9px] rounded-[7px] px-[10px] py-[6px] text-[13px] text-text no-underline hover:bg-white/[0.04]"
            >
              <span
                className={`h-[6px] w-[6px] rounded-full ${
                  p.tone === "accent" ? "bg-accent" : "bg-neutral-600"
                }`}
              />
              {p.name}
              <span className="ml-auto text-[11px] opacity-40">{p.count}</span>
            </Link>
          ))}
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <div className="px-[10px] text-[10px] uppercase tracking-[0.1em] text-text/[0.38]">
          タグ
        </div>
        <div className="flex flex-wrap gap-[5px] px-[10px]">
          {tags.slice(0, 4).map((t) => (
            <Link key={t.id} href={`/library?tag=${encodeURIComponent(t.label)}`}>
              <Tag tone={t.tone === "accent" ? "accent" : "neutral"}>
                {t.label}
              </Tag>
            </Link>
          ))}
          {tags.length > 4 && <Tag tone="outline">+{tags.length - 4}</Tag>}
        </div>
      </div>

      <div className="mt-auto flex flex-col gap-[7px] rounded-[9px] bg-surface p-3 shadow-[0_0_0_1px_var(--color-neutral-900)]">
        <div className="text-[11px] text-text/50">今日の霧</div>
        <div className="text-[12.5px] leading-[1.55]">
          {digest?.message ?? "…"}
        </div>
        <button
          className="btn btn-primary self-start px-[9px] py-[5px] text-[12px]"
          onClick={sortAll}
          disabled={sorting}
        >
          <Icon name="sparkle" />
          {sorting ? "振り分け中…" : "まとめて振り分け"}
        </button>
      </div>
    </aside>
  );
}

