import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // The dummy backend keeps everything in memory, so nothing to configure here.

  // Keep the dev build indicator out of the sidebar's bottom-left corner.
  devIndicators: { position: "bottom-right" },
};

export default nextConfig;

===== hazy-note/postcss.config.mjs =====
const config = {
  plugins: ["@tailwindcss/postcss"],
};

export default config;

===== hazy-note/middleware.ts =====
import { clerkMiddleware, createRouteMatcher } from "@clerk/nextjs/server";

// Everything under /api and every page needs a signed-in user except the
// Clerk auth pages themselves — this is a single-tenant-per-user notes app,
// there's no public read path.
const isPublicRoute = createRouteMatcher(["/sign-in(.*)", "/sign-up(.*)"]);

export default clerkMiddleware(async (auth, req) => {
  if (!isPublicRoute(req)) {
    await auth.protect();
  }
});

export const config = {
  matcher: [
    "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    "/(api|trpc)(.*)",
  ],
};

===== hazy-note/lib/db/index.ts =====
import { drizzle } from "drizzle-orm/node-postgres";
import { Pool } from "pg";
import * as schema from "./schema";
import * as relations from "./relations";

// Next.js loads .env.local automatically; this just fails loudly if it is missing.
if (!process.env.DATABASE_URL) {
  throw new Error("DATABASE_URL is not set — check .env.local");
}

// Reuse one pool across dev hot-reloads instead of leaking a pool per reload,
// same pattern as the legacy in-memory store's globalThis.__hazyDB singleton.
const globalForDb = globalThis as unknown as { __hazyPool?: Pool };

const pool =
  globalForDb.__hazyPool ??
  new Pool({ connectionString: process.env.DATABASE_URL });

if (process.env.NODE_ENV !== "production") {
  globalForDb.__hazyPool = pool;
}

export const db = drizzle(pool, {
  schema: { ...schema, ...relations },
});

export { schema };

