1	import { and, desc, eq, isNull, sql } from "drizzle-orm";
2	import { db, schema } from "./index";
3	import { fetchAndExtract } from "@/lib/extract";
4	import {
5	  rewriteForExport,
6	  suggestConnections,
7	  summariseMemo,
8	  summariseSource,
9	  synthesiseCompare,
10	} from "@/lib/ai";
11	import type {
12	  Item,
13	  Note,
14	  NoteBlock,
15	  Project,
16	  Tag,
17	  CompareBoard,
18	  GraphData,
19	  Digest,
20	  SourceKind,
21	  ExportDraft,
22	  ExportFormat,
23	} from "@/lib/types";
24	
25	// ─────────────────────────────────────────────────────────────
26	// Every function here is scoped by the caller's internal `users.id` (see
27	// lib/db/current-user.ts). This is the real replacement for lib/store.ts —
28	// same function names and return shapes, backed by Postgres instead of a
29	// mutable object on globalThis.
30	// ─────────────────────────────────────────────────────────────
31	
32	function relativeLabel(iso: string): string {
33	  const min = Math.floor((Date.now() - new Date(iso).getTime()) / 60_000);
34	  if (min < 1) return "たった今";
35	  if (min < 60) return `${min}分前`;
36	  const hours = Math.floor(min / 60);
37	  if (hours < 24) return "今日";
38	  const days = Math.floor(hours / 24);
39	  return days === 1 ? "昨日" : `${days}日前`;
40	}
41	
42	function kindFromUrl(url: string): SourceKind {
43	  const u = url.toLowerCase();
44	  if (u.includes("youtube") || u.includes("youtu.be") || u.includes("vimeo"))
45	    return "video";
46	  if (u.endsWith(".pdf") || u.includes("arxiv.org")) return "pdf";
47	  if (u.includes("twitter.com") || u.includes("x.com") || u.includes("bsky"))
48	    return "thread";
49	  return "article";
50	}
51	
52	function siteFromUrl(url: string): string {
53	  try {
54	    return new URL(url).hostname.replace(/^www\./, "");
55	  } catch {
56	    return url.slice(0, 40);
57	  }
58	}
59	
60	function normalizeUrl(url: string): string {
61	  try {
62	    const u = new URL(url);
63	    return `${u.hostname.replace(/^www\./, "")}${u.pathname.replace(/\/+$/, "")}${u.search}`.toLowerCase();
64	  } catch {
65	    return url.trim().toLowerCase();
66	  }
67	}
68	
69	// ── Items ──────────────────────────────────────────────────
70	type SavedUrlWithLinks = typeof schema.saved_urls.$inferSelect & {
71	  collection_items: { collection_id: string }[];
72	};
73	
74	function toItem(row: SavedUrlWithLinks): Item {
75	  const site =
76	    row.kind === "note" ? (row.domain ?? "メモ") : (row.domain ?? siteFromUrl(row.url));
77	  return {
78	    id: row.id,
79	    url: row.url,
80	    kind: row.kind as SourceKind,
81	    site,
82	    title: row.title ?? site,
83	    addedAt: new Date(row.created_at).toISOString(),
84	    addedLabel: relativeLabel(row.created_at),
85	    status: row.fetch_status === "success" ? "ready" : row.fetch_status === "error" ? "ready" : "reading",
86	    durationLabel: row.duration_label ?? undefined,
87	    summary: row.summary_lines,
88	    points: row.points,
89	    suggestedTags: row.suggested_tags,
90	    tags: row.tags,
91	    projectId: row.collection_items[0]?.collection_id ?? null,
92	    quoteCandidates: row.quote_candidates,
93	    relatedNoteId: row.related_note_id ?? undefined,
94	  };
95	}
96	
97	export async function listItems(userId: string): Promise<Item[]> {
98	  const rows = await db.query.saved_urls.findMany({
99	    where: (t, { eq }) => eq(t.user_id, userId),
100	    with: { collection_items: true },
101	    orderBy: (t, { desc }) => [desc(t.created_at)],
102	  });
103	  return rows.map(toItem);
104	}
105	
106	/**
107	 * GET /api/items/importable — the "Hazyから追加" picker in the capture flow.
108	 * Every URL the user has in the hazy database (the `saved_urls` table this
109	 * app is connected to), newest first, so they can pull one into the note
110	 * pipeline (`/capture?id=…` → finishReading → 要約とタグ → 置き場所).
111	 *
112	 * Pasted memos (`kind: "note"`) are excluded — this is for real URLs. Items
113	 * hazy-note has already worked on (summary generated, or filed into a
114	 * project) are still listed; the picker marks them so and selecting one just
115	 * re-opens it. Unworked items sort to the top.
116	 */
117	export async function listImportable(userId: string): Promise<Item[]> {
118	  const rows = await db.query.saved_urls.findMany({
119	    where: (t, { and, eq, ne }) =>
120	      and(eq(t.user_id, userId), ne(t.kind, "note")),
121	    with: { collection_items: true },
122	    orderBy: (t, { desc }) => [desc(t.created_at)],
123	  });
124	  const items = rows.map(toItem);
125	  const worked = (it: Item) => it.summary.length > 0 || it.projectId !== null;
126	  return [...items.filter((it) => !worked(it)), ...items.filter(worked)];
127	}
128	
129	export async function getItem(userId: string, id: string): Promise<Item | undefined> {
130	  const row = await db.query.saved_urls.findFirst({
131	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
132	    with: { collection_items: true },
133	  });
134	  return row ? toItem(row) : undefined;
135	}
136	
137	export async function addItem(userId: string, url: string): Promise<Item> {
138	  const site = siteFromUrl(url);
139	  const [row] = await db
140	    .insert(schema.saved_urls)
141	    .values({
142	      user_id: userId,
143	      url,
144	      normalized_url: normalizeUrl(url),
145	      domain: site,
146	      title: site,
147	      kind: kindFromUrl(url),
148	      fetch_status: "pending",
149	    })
150	    .onConflictDoUpdate({
151	      target: [schema.saved_urls.user_id, schema.saved_urls.normalized_url],
152	      set: { fetch_status: "pending", updated_at: new Date().toISOString() },
153	    })
154	    .returning();
155	  return (await getItem(userId, row.id))!;
156	}
157	
158	/**
159	 * POST /api/items — the "Hazyから追加" path. A pasted memo becomes an item with
160	 * no external URL; `kind: "note"` and the raw text lives in `extracted_text`.
161	 */
162	export async function addMemo(userId: string, text: string): Promise<Item> {
163	  const token = `hazy:memo:${crypto.randomUUID()}`;
164	  const firstLine = text.trim().split("\n")[0].trim();
165	  const title =
166	    firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine || "メモ";
167	  const [row] = await db
168	    .insert(schema.saved_urls)
169	    .values({
170	      user_id: userId,
171	      url: token,
172	      normalized_url: token,
173	      domain: "メモ",
174	      title,
175	      kind: "note",
176	      extracted_text: text,
177	      fetch_status: "pending",
178	    })
179	    .returning();
180	  return (await getItem(userId, row.id))!;
181	}
182	
183	/**
184	 * POST /api/items/:id/read — the "読み取り" step. For a URL this fetches the
185	 * page, extracts its text, and asks the model for a summary + tags. For a
186	 * pasted memo it just distils what was written. Best-effort: a fetch or AI
187	 * failure still resolves the item (fetch_status "error") instead of throwing.
188	 *
189	 * "Hazyから追加" fast path: an item saved via the hazy app already has its
190	 * page text in `extracted_text`. If it's substantial, summarise straight from
191	 * that — no second network fetch, and a transient fetch failure can't downgrade
192	 * an item hazy already read successfully.
193	 */
194	export async function finishReading(userId: string, id: string): Promise<Item | undefined> {
195	  const existing = await db.query.saved_urls.findFirst({
196	    where: (t, { and, eq }) => and(eq(t.id, id), eq(t.user_id, userId)),
197	  });
198	  if (!existing) return undefined;
199	
200	  if (existing.kind !== "note" && (existing.extracted_text?.trim().length ?? 0) >= 400) {
201	    const title =
202	      existing.title && existing.title !== existing.domain
203	        ? existing.title
204	        : (existing.domain ?? siteFromUrl(existing.url));
205	    const digest = await summariseSource({
206	      title,
207	      text: existing.extracted_text ?? "",
208	      kind: existing.kind,
209	    });
210	    await db
211	      .update(schema.saved_urls)
212	      .set({
213	        fetch_status: "success",
214	        title: digest.title?.trim() || title,
215	        duration_label:
216	          existing.duration_label ??
217	          (existing.estimated_read_minutes
218	            ? `読了${existing.estimated_read_minutes}分`
219	            : null),
220	        summary_lines: digest.summary,
221	        points: digest.points,
222	        suggested_tags: digest.suggestedTags,
223	        updated_at: new Date().toISOString(),
224	      })
225	      .where(eq(schema.saved_urls.id, id));
226	    return getItem(userId, id);
227	  }
228	
229	  if (existing.kind === "note") {
230	    const digest = await summariseMemo(existing.extracted_text ?? "");
231	    await db
232	      .update(schema.saved_urls)
233	      .set({
234	        fetch_status: "success",
235	        summary_lines: digest.summary,
236	        points: digest.points,
237	        suggested_tags: digest.suggestedTags,
238	        updated_at: new Date().toISOString(),
239	      })
240	      .where(eq(schema.saved_urls.id, id));
241	    return getItem(userId, id);
242	  }
243	
244	  let extracted;
245	  try {
246	    extracted = await fetchAndExtract(existing.url);
247	  } catch (e) {
248	    await db
249	      .update(schema.saved_urls)
250	      .set({
251	        fetch_status: "error",
252	        fetch_error: (e as Error).message.slice(0, 500),
253	        updated_at: new Date().toISOString(),
254	      })
255	      .where(eq(schema.saved_urls.id, id));
256	    return getItem(userId, id);
257	  }
258	
259	  const title =
260	    extracted.title?.trim() ||
261	    (existing.title && existing.title !== existing.domain
262	      ? existing.title
263	      : (existing.domain ?? siteFromUrl(existing.url)));
264	
265	  const digest = await summariseSource({
266	    title,
267	    text: extracted.text,
268	    kind: existing.kind,
269	  });
270	
271	  await db
272	    .update(schema.saved_urls)
273	    .set({
274	      fetch_status: "success",
275	      title: digest.title?.trim() || title,
276	      description: extracted.description ?? existing.description,
277	      favicon_url: extracted.favicon ?? existing.favicon_url,
278	      og_image_url: extracted.ogImage ?? existing.og_image_url,
279	      extracted_text: extracted.text || existing.extracted_text,
280	      content_language: extracted.lang ?? existing.content_language,
281	      estimated_read_minutes: extracted.readMinutes ?? existing.estimated_read_minutes,
282	      duration_label:
283	        existing.duration_label ??
