33	function relativeLabel(when: Date | string): string {
34	  const min = Math.floor((Date.now() - new Date(when).getTime()) / 60_000);
35	  if (min < 1) return "たった今";
36	  if (min < 60) return `${min}分前`;
37	  const hours = Math.floor(min / 60);
38	  if (hours < 24) return "今日";
39	  const days = Math.floor(hours / 24);
40	  return days === 1 ? "昨日" : `${days}日前`;
41	}
