45	  if (u.includes("youtube") || u.includes("youtu.be") || u.includes("vimeo")) return "video";
46	  if (u.endsWith(".pdf") || u.includes("arxiv.org")) return "pdf";
47	  if (u.includes("twitter.com") || u.includes("x.com") || u.includes("bsky")) return "thread";
