17	  const [refs, setRefs] = useState("list");
18	  const [toast, setToast] = useState<string | null>(null);
19	  const [loading, setLoading] = useState(true);
20	
21	  useEffect(() => {
22	    api.notes().then((ns) => {
23	      setNotes(ns);
24	      setNoteId((cur) => cur || ns[0]?.id || "");
25	    });
26	  }, []);
27	
28	  useEffect(() => {
29	    setLoading(true);
30	    api
31	      .export(noteId, format)
32	      .then(setDraft)
33	      .catch(() => setDraft(null))
34	      .finally(() => setLoading(false));
35	  }, [format, noteId]);
36	
37	  async function run() {
38	    const r = await api.runExport(noteId, format);
39	    setToast(`書き出しました → ${r.exportedTo}`);
40	    setTimeout(() => setToast(null), 3200);
41	  }
42	
43	  return (
44	    <div className="grid min-h-screen grid-cols-1 lg:grid-cols-[1fr_320px]">
45	      <main className="flex flex-col gap-[18px] p-[28px_44px_34px]">
46	        <div className="flex items-center gap-[10px]">
47	          <Seg
48	            name="exfmt"
49	            value={format}
50	            onChange={setFormat}
51	            options={[
52	              { value: "blog", label: "ブログ記事" },
53	              { value: "memo", label: "社内共有メモ" },
54	              { value: "bullets", label: "要点だけ" },
55	            ]}
56	          />
57	          {notes.length > 0 && (
58	            <select
59	              className="input w-auto py-[5px] text-[12px]"
60	              value={noteId}
61	              onChange={(e) => setNoteId(e.target.value)}
62	            >
63	              {notes.map((n) => (
64	                <option key={n.id} value={n.id}>
65	                  {n.title}
66	                </option>
67	              ))}
68	            </select>
69	          )}
70	          <div className="ml-auto flex gap-2">
71	            <Button className="text-[13px]">
72	              <Icon name="markdown-logo" /> Markdown
73	            </Button>
74	            <Button variant="primary" className="text-[13px]" onClick={run}>
75	              <Icon name="export" /> 書き出す
76	            </Button>
77	          </div>
78	        </div>
79	        <div className="hr" />
80	
81	        {toast && (
82	          <div className="flex items-center gap-2 rounded-lg bg-accent/[0.1] px-3 py-2 text-[13px] text-accent-300 shadow-[0_0_0_1px_var(--color-accent-800)]">
83	            <Icon name="check-circle" size={15} /> {toast}
84	          </div>
85	        )}
86	
87	        {loading && !draft && (
88	          <div className="text-[13px] text-text/40">下書きを生成しています…</div>
89	        )}
90	
91	        {draft && (
92	          <div className="flex max-w-[62ch] flex-col gap-4">
93	            <div className="text-[11px] uppercase tracking-[0.1em] text-text/[0.42]">
94	              下書き · {draft.meta}
95	            </div>
96	            <h2 className="tracking-[-0.025em]">{draft.title}</h2>
97	            {draft.blocks.map((b, i) => {
98	              if (b.type === "h4")
99	                return (
100	                  <h4 key={i} className="mt-2">
101	                    {b.text}
102	                  </h4>
103	                );
104	              if (b.type === "note")
105	                return (
106	                  <div
107	                    key={i}
108	                    className="flex items-center gap-[9px] rounded-lg bg-accent/[0.07] px-[13px] py-[11px] text-[13px] leading-[1.6] shadow-[0_0_0_1px_var(--color-accent-800)]"
109	                  >
110	                    <Icon name="warning-circle" size={16} className="text-accent-400" />
111	                    {b.text}
112	                  </div>
113	                );
114	              return (
115	                <p
116	                  key={i}
117	                  className={`m-0 text-[15px] leading-[1.9] ${b.dim ? "opacity-55" : "opacity-90"}`}
118	                >
119	                  {b.text}
120	                  {b.dim && noteId && (
121	                    <>
122	                      {" "}
123	                      <Link href={`/notes/${noteId}`}>ノートで埋める</Link>
124	                    </>
125	                  )}
126	                </p>
127	              );
128	            })}
129	            {draft.warning && (
130	              <div className="flex items-center gap-[9px] rounded-lg bg-accent/[0.07] px-[13px] py-[11px] text-[13px] leading-[1.6] shadow-[0_0_0_1px_var(--color-accent-800)]">
131	                <Icon name="warning-circle" size={16} className="text-accent-400" />
132	                {draft.warning}
133	              </div>
134	            )}
135	          </div>
136	        )}
137	      </main>
138	
139	      <aside className="flex flex-col gap-4 bg-neutral-900 p-[22px_18px]">
140	        <div className="text-[10px] uppercase tracking-[0.09em] text-text/40">どこから来たか</div>
141	        <div className="flex flex-col gap-2">
