1	"use client";
2	
3	import Link from "next/link";
4	import { useSearchParams } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { Icon } from "@/components/icon";
7	import { Button, Seg } from "@/components/ui";
8	import { api } from "@/lib/api";
9	import type { ExportDraft, ExportFormat, Note } from "@/lib/types";
10	
11	export function ExportClient() {
12	  const sp = useSearchParams();
13	  const [format, setFormat] = useState<ExportFormat>("blog");
14	  const [draft, setDraft] = useState<ExportDraft | null>(null);
15	  const [notes, setNotes] = useState<Note[]>([]);
16	  const [noteId, setNoteId] = useState<string>(sp.get("noteId") ?? "");
17	  const [refs, setRefs] = useState("list");
18	  const [toast, setToast] = useState<string | null>(null);
19	  const [loading, setLoading] = useState(true);
20	
21	  useEffect(() => {
22	    api.notes().then((ns) => {
23	      setNotes(ns);
24	      setNoteId((cur) => cur || ns[0]?.id || "");
25	    });
26	  }, []);
27	
28	  useEffect(() => {
29	    setLoading(true);
30	    api
31	      .export(noteId, format)
32	      .then(setDraft)
33	      .catch(() => setDraft(null))
34	      .finally(() => setLoading(false));
35	  }, [format, noteId]);
36	
37	  async function run() {
38	    const r = await api.runExport(noteId, format);
39	    setToast(`書き出しました → ${r.exportedTo}`);
40	    setTimeout(() => setToast(null), 3200);
41	  }
42	
43	  return (
44	    <div className="grid min-h-screen grid-cols-1 lg:grid-cols-[1fr_320px]">
45	      <main className="flex flex-col gap-[18px] p-[28px_44px_34px]">
46	        <div className="flex items-center gap-[10px]">
47	          <Seg
48	            name="exfmt"
49	            value={format}
50	            onChange={setFormat}
51	            options={[
52	              { value: "blog", label: "ブログ記事" },
53	              { value: "memo", label: "社内共有メモ" },
54	              { value: "bullets", label: "要点だけ" },
55	            ]}
56	          />
57	          {notes.length > 0 && (
58	            <select
59	              className="input w-auto py-[5px] text-[12px]"
60	              value={noteId}
61	              onChange={(e) => setNoteId(e.target.value)}
