    fetch(`/api/notes/${id}/suggestion`, opts("POST", { blockIndex, action })).then(j<Note>),

  compare: () => fetch("/api/compare", { cache: "no-store" }).then(j<CompareBoard>),
  rebuildCompare: (projectId?: string) =>
    fetch("/api/compare", opts("POST", projectId ? { projectId } : {})).then(j<CompareBoard>),

  graph: () => fetch("/api/graph", { cache: "no-store" }).then(j<GraphData>),
  rebuildGraph: () => fetch("/api/graph", opts("POST")).then(j<GraphData>),

  export: (noteId: string, format: ExportFormat) =>
    fetch(`/api/export?noteId=${noteId}&format=${format}`, {
      cache: "no-store",
    }).then(j<ExportDraft>),
  runExport: (noteId: string, format: ExportFormat) =>
    fetch("/api/export", opts("POST", { noteId, format })).then(
      j<ExportDraft & { exportedTo: string }>
    ),
};
=== suggestion route ===
import { type NextRequest, NextResponse } from "next/server";
import { requireAppUser } from "@/lib/db/current-user";
import { acceptSuggestion, dismissSuggestion } from "@/lib/db/repo";

export const dynamic = "force-dynamic";

type Ctx = { params: Promise<{ id: string }> };

/** body: { blockIndex: number, action: "accept" | "dismiss" } */
export async function POST(req: NextRequest, { params }: Ctx) {
  const user = await requireAppUser();
  const { id } = await params;
  const body = await req.json().catch(() => ({}));
  const blockIndex = Number(body.blockIndex);
  const action = body.action;
  if (!Number.isInteger(blockIndex) || (action !== "accept" && action !== "dismiss")) {
    return NextResponse.json({ error: "bad request" }, { status: 400 });
  }
  const note =
    action === "accept"
      ? await acceptSuggestion(user.id, id, blockIndex)
      : await dismissSuggestion(user.id, id, blockIndex);
  if (!note) return NextResponse.json({ error: "not found" }, { status: 404 });
  return NextResponse.json(note);
}

