31	  /** Serialise writes: overlapping saves would race and lose updates (each
32	   * PATCH replaces the whole `blocks` array). */
33	  async function write(fn: () => Promise<Note>) {
34	    if (saving) return;
35	    setSaving(true);
36	    try {
37	      setNote(await fn());
38	    } finally {
39	      setSaving(false);
40	    }
41	  }
