52	    if (!current || !("text" in current) || current.text === text) return;
53	    if (!text.trim()) {
54	      await deleteBlock(i);
55	      return;
56	    }
57	    const blocks = note.blocks.map((b, j) => (j === i ? { ...b, text } : b));
58	    await saveBlocks(blocks);
59	  }
