1	"use client";
2	
3	import Link from "next/link";
4	import { useRouter } from "next/navigation";
5	import { useCallback, useEffect, useRef, useState } from "react";
6	import { Icon } from "@/components/icon";
7	import { Loading, Spinner } from "@/components/loading";
8	import { Button } from "@/components/ui";
9	import { api } from "@/lib/api";
10	import type { Note, NoteBlock } from "@/lib/types";
11	
12	export function NoteClient({ id }: { id: string }) {
13	  const router = useRouter();
14	  const [note, setNote] = useState<Note | null>(null);
15	  const [showInline, setShowInline] = useState(true);
16	  const [draft, setDraft] = useState("");
17	  const [notFound, setNotFound] = useState(false);
18	  const [saving, setSaving] = useState(false);
19	
20	  const load = useCallback(
21	    () =>
22	      api
23	        .note(id)
24	        .then(setNote)
25	        .catch(() => setNotFound(true)),
26	    [id],
27	  );
28	  useEffect(() => {
29	    load();
30	  }, [load]);
31	
32	  /** Serialise writes: overlapping saves would race and lose updates (each
33	   * PATCH replaces the whole `blocks` array). */
34	  async function write(fn: () => Promise<Note>) {
35	    if (saving) return;
36	    setSaving(true);
37	    try {
38	      setNote(await fn());
39	    } finally {
40	      setSaving(false);
41	    }
42	  }
43	
44	  const saveBlocks = (blocks: NoteBlock[]) => write(() => api.updateNote(id, { blocks }));
45	
46	  async function act(i: number, action: "accept" | "dismiss") {
47	    await write(() => api.suggestion(id, i, action));
48	  }
49	
50	  async function editBlockText(i: number, text: string) {
51	    if (!note) return;
52	    const current = note.blocks[i];
53	    if (!current || !("text" in current) || current.text === text) return;
54	    if (!text.trim()) {
55	      await deleteBlock(i);
56	      return;
57	    }
58	    const blocks = note.blocks.map((b, j) => (j === i ? { ...b, text } : b));
59	    await saveBlocks(blocks);
60	  }
61	
62	  async function deleteBlock(i: number) {
63	    if (!note) return;
64	    await saveBlocks(note.blocks.filter((_, j) => j !== i));
65	  }
66	
67	  async function addParagraph() {
68	    const text = draft.trim();
69	    if (!text) return;
70	    setDraft("");
71	    await write(() => api.appendParagraph(id, text));
72	  }
73	
74	  async function addTag() {
75	    if (!note) return;
76	    const label = window.prompt("タグ")?.trim();
77	    if (!label || note.tags.some((t) => t.label === label)) return;
78	    await write(() =>
79	      api.updateNote(id, { tags: [...note.tags, { label, tone: "neutral" }] }),
80	    );
81	  }
82	
83	  async function removeTag(label: string) {
84	    if (!note) return;
85	    await write(() => api.updateNote(id, { tags: note.tags.filter((t) => t.label !== label) }));
86	  }
87	
88	  async function toggleStatus() {
89	    if (!note) return;
90	    await write(() =>
91	      api.updateNote(id, { status: note.status === "done" ? "draft" : "done" }),
92	    );
93	  }
94	
95	  async function renameNote() {
96	    const title = window.prompt("ノートのタイトル", note?.title ?? "");
97	    if (title == null) return;
98	    await write(() => api.updateNote(id, { title }));
99	  }
100	
101	  async function removeNote() {
102	    if (!window.confirm("このノートを削除しますか？")) return;
103	    await api.deleteNote(id);
104	    router.push("/notes");
105	  }
