"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { Icon } from "@/components/icon";
import { Loading, Spinner } from "@/components/loading";
import { Button } from "@/components/ui";
import { api } from "@/lib/api";
import type { Note, NoteBlock } from "@/lib/types";

export function NoteClient({ id }: { id: string }) {
  const router = useRouter();
  const [note, setNote] = useState<Note | null>(null);
  const [showInline, setShowInline] = useState(true);
  const [draft, setDraft] = useState("");
  const [notFound, setNotFound] = useState(false);
  const [saving, setSaving] = useState(false);

  const load = useCallback(
    () =>
      api
        .note(id)
        .then(setNote)
        .catch(() => setNotFound(true)),
    [id],
  );
  useEffect(() => {
    load();
  }, [load]);

  /** Serialise writes: overlapping saves would race and lose updates (each
   * PATCH replaces the whole `blocks` array). */
  async function write(fn: () => Promise<Note>) {
    if (saving) return;
    setSaving(true);
    try {
      setNote(await fn());
    } finally {
      setSaving(false);
    }
  }

  const saveBlocks = (blocks: NoteBlock[]) => write(() => api.updateNote(id, { blocks }));

  async function act(i: number, action: "accept" | "dismiss") {
    await write(() => api.suggestion(id, i, action));
  }

  async function editBlockText(i: number, text: string) {
    if (!note) return;
    const current = note.blocks[i];
    if (!current || !("text" in current) || current.text === text) return;
    if (!text.trim()) {
      await deleteBlock(i);
      return;
    }
    const blocks = note.blocks.map((b, j) => (j === i ? { ...b, text } : b));
    await saveBlocks(blocks);
  }

  async function deleteBlock(i: number) {
    if (!note) return;
    await saveBlocks(note.blocks.filter((_, j) => j !== i));
  }

  async function addParagraph() {
    const text = draft.trim();
    if (!text) return;
    setDraft("");
    await write(() => api.appendParagraph(id, text));
  }

  async function addTag() {
    if (!note) return;
    const label = window.prompt("タグ")?.trim();
    if (!label || note.tags.some((t) => t.label === label)) return;
    await write(() =>
      api.updateNote(id, { tags: [...note.tags, { label, tone: "neutral" }] }),
    );
  }

  async function removeTag(label: string) {
    if (!note) return;
    await write(() => api.updateNote(id, { tags: note.tags.filter((t) => t.label !== label) }));
  }

  async function toggleStatus() {
    if (!note) return;
    await write(() =>
      api.updateNote(id, { status: note.status === "done" ? "draft" : "done" }),
    );
  }

  async function renameNote() {
    const title = window.prompt("ノートのタイトル", note?.title ?? "");
    if (title == null) return;
    await write(() => api.updateNote(id, { title }));
  }

  async function removeNote() {
    if (!window.confirm("このノートを削除しますか？")) return;
    await api.deleteNote(id);
    router.push("/notes");
  }

  if (notFound) return <div className="p-8 text-text/50">ノートが見つかりません。</div>;
  if (!note) return <Loading label="ノートを開いています" />;

