async function deleteBlock(i: number) {
  if (!note) return;
  await persist({ ...note, blocks: note.blocks.filter((_, j) => j !== i) });
}

async function addParagraph() {
  const text = draft.trim();
  if (!text || !note) return;
  setDraft("");
  await persist({ ...note, blocks: [...note.blocks, { type: "p", text }] });
}

async function addTag() {
  if (!note) return;
  const label = window.prompt("タグ")?.trim();
  if (!label || note.tags.some((t) => t.label === label)) return;
  await persist({ ...note, tags: [...note.tags, { label, tone: "neutral" }] });
}

