"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { Icon } from "@/components/icon";
import { Loading, Spinner } from "@/components/loading";
import { Button } from "@/components/ui";
import { api } from "@/lib/api";
import type { Note, NoteBlock } from "@/lib/types";

const BLANK: Note = {
  id: "",
  title: "無題のノート",
  projectId: "",
  tags: [],
  status: "draft",
  updatedLabel: "まだ保存していません",
  blocks: [],
  sources: [],
  links: [],
  flags: [],
};

/** `id` is undefined for the `/notes/new` draft — nothing is written to the
 *  DB until the first real edit. */
export function NoteClient({ id }: { id?: string }) {
  const router = useRouter();
  const [noteId, setNoteId] = useState<string | undefined>(id);
  const [note, setNote] = useState<Note | null>(id ? null : BLANK);
  const [showInline, setShowInline] = useState(true);
  const [draft, setDraft] = useState("");
  const [notFound, setNotFound] = useState(false);
  const [saving, setSaving] = useState(false);
  const isDraft = !noteId;

  const load = useCallback(() => {
    if (!noteId) return;
    api
      .note(noteId)
      .then(setNote)
      .catch(() => setNotFound(true));
  }, [noteId]);
  useEffect(() => {
    load();
  }, [load]);

  /**
   * Apply an edit. Serialised — overlapping saves race (each write replaces the
   * whole note). On a `/notes/new` draft the first edit is what actually
   * creates the row; after that it's a normal PATCH and the URL is swapped in
   * place (no navigation, no lost focus).
   */
  async function persist(next: Note) {
    if (saving) return;
    setSaving(true);
    setNote(next); // optimistic
    try {
      if (noteId) {
        setNote(
          await api.updateNote(noteId, {
            title: next.title,
            blocks: next.blocks,
            tags: next.tags,
            status: next.status,
          }),
        );
      } else {
        const created = await api.addNote({
          title: next.title,
          blocks: next.blocks,
          tags: next.tags,
          status: next.status,
        });
        setNoteId(created.id);
        window.history.replaceState(null, "", `/notes/${created.id}`);
        setNote(created);
      }
    } finally {
      setSaving(false);
    }
  }

  async function act(i: number, action: "accept" | "dismiss") {
    if (!noteId || saving) return; // suggestions only exist on saved notes
    setSaving(true);
    try {
      setNote(await api.suggestion(noteId, i, action));
    } finally {
      setSaving(false);
    }
  }

  async function editBlockText(i: number, text: string) {
    if (!note) return;
    const current = note.blocks[i];
    if (!current || !("text" in current) || current.text === text) return;
    if (!text.trim()) {
      await deleteBlock(i);
      return;
    }
    await persist({ ...note, blocks: note.blocks.map((b, j) => (j === i ? { ...b, text } : b)) });
  }

  async function deleteBlock(i: number) {
    if (!note) return;
    await persist({ ...note, blocks: note.blocks.filter((_, j) => j !== i) });
  }

  async function addParagraph() {
    const text = draft.trim();
    if (!text || !note) return;
    setDraft("");
    await persist({ ...note, blocks: [...note.blocks, { type: "p", text }] });
  }

  async function addTag() {
    if (!note) return;
    const label = window.prompt("タグ")?.trim();
    if (!label || note.tags.some((t) => t.label === label)) return;
    await persist({ ...note, tags: [...note.tags, { label, tone: "neutral" }] });
  }

  async function removeTag(label: string) {
    if (!note) return;
    await persist({ ...note, tags: note.tags.filter((t) => t.label !== label) });
  }

  async function toggleStatus() {
    if (!note) return;
    await persist({ ...note, status: note.status === "done" ? "draft" : "done" });
  }

  async function renameNote() {
    if (!note) return;
    const title = window.prompt("ノートのタイトル", note.title);
    if (title == null || title === note.title) return;
    await persist({ ...note, title });
  }

  async function removeNote() {
    if (isDraft) return router.push("/notes");
    if (!window.confirm("このノートを削除しますか？")) return;
    await api.deleteNote(noteId as string);
    router.push("/notes");
  }

  if (notFound) return <div className="p-8 text-text/50">ノートが見つかりません。</div>;
  if (!note) return <Loading label="ノートを開いています" />;

  return (
    <div className="grid min-h-screen grid-cols-1 lg:grid-cols-[1fr_260px]">
      <main className="flex flex-col gap-4 p-[28px_44px_34px]">
        <div className="flex items-center gap-[10px] text-[12px] text-text/45">
          <Icon name="notebook" />
          ノート
          <Icon name="caret-right" size={11} />
          <span className="text-text">{note.title}</span>

